package com.haolin.vontlocal;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;

/** Emulator UI/pixel/real AppWidgetHost checks. Never sends lamp commands. */
public final class WidgetOpacityAcceptance extends UiAcceptance {
    AppWidgetHost host;AppWidgetHostView hosted;int widgetId;
    Button button(Activity a,String text){for(View v:nodes(a.getWindow().getDecorView()))if(v instanceof Button&&((Button)v).getText().toString().equals(text))return(Button)v;throw new IllegalArgumentException(text);}
    void waitHost(int expected)throws Exception{long end=SystemClock.elapsedRealtime()+4000;while(SystemClock.elapsedRealtime()<end){if(main(()->{ImageView v=hosted.findViewById(R.id.widget_background_layer);return v!=null&&v.getImageAlpha()==expected;})){check(true,"bound widget received background alpha "+expected);return;}SystemClock.sleep(50);}throw new IOException("Bound widget alpha not updated to "+expected);}
    void bindHost()throws Exception{main(()->{host=new AppWidgetHost(context(),8202);widgetId=host.allocateAppWidgetId();Bundle size=new Bundle();size.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,360);size.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH,360);size.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,124);size.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,124);AppWidgetManager manager=AppWidgetManager.getInstance(context());check(manager.bindAppWidgetIdIfAllowed(widgetId,new ComponentName(context(),LinkWidget.class),size),"bind widget to emulator test host");host.startListening();hosted=host.createView(context(),widgetId,manager.getAppWidgetInfo(widgetId));LinkWidget.updateAll(context());return true;});waitHost(255);}
    void pixels(String theme,int n,boolean wide)throws Exception{context().getSharedPreferences("appearance-v1",0).edit().putString("theme",theme).commit();WidgetAppearance.save(context(),n);FrameLayout parent=new FrameLayout(context());View view=LinkWidget.views(context(),wide,360).apply(context(),parent);int w=Ui.dp(context(),wide?360:180),h=Ui.dp(context(),wide?124:188);view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));view.layout(0,0,w,h);Bitmap image=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);view.draw(new Canvas(image));int actual=Color.alpha(image.getPixel(w/2,Ui.dp(context(),5)));check(Math.abs(actual-WidgetAppearance.alpha(n))<=1,"background pixel alpha "+theme+":"+wide+":"+n);check(((ImageView)view.findViewById(R.id.widget_background_layer)).getImageAlpha()==WidgetAppearance.alpha(n),"background layer alpha only");TextView text=view.findViewById(R.id.widget_work_label);check(text.getAlpha()==1&&Color.alpha(text.getCurrentTextColor())==255,"scene text stays opaque");for(int id:new int[]{R.id.widget_work,R.id.widget_wind_down,R.id.widget_sleep,R.id.widget_off,R.id.widget_focus_action,R.id.widget_title_area,R.id.widget_focus_info})check(view.findViewById(id).hasOnClickListeners(),"widget entry retained "+id);image.recycle();}
    void drag(SeekBar slider,int percent)throws Exception{main(()->{slider.requestRectangleOnScreen(new Rect(0,0,slider.getWidth(),slider.getHeight()),true);return true;});waitForIdleSync();int[] geometry=main(()->{int[] xy=new int[2];slider.getLocationOnScreen(xy);return new int[]{xy[0]+slider.getPaddingLeft(),xy[1]+slider.getHeight()/2,slider.getWidth()-slider.getPaddingLeft()-slider.getPaddingRight()};});long down=SystemClock.uptimeMillis();for(int i=0;i<=4;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==4?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;float x=geometry[0]+geometry[2]*percent/100f*i/4;MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,geometry[1],0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"slider touch event "+i);e.recycle();SystemClock.sleep(20);}waitForIdleSync();}
    @Override public void onStart(){int code=0;try{
        check(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"),"emulator only");check(!new File(context().getFilesDir(),ScreenbarClient.SEALED).exists(),"no lamp credential present");folder=new File(context().getFilesDir(),"opacity-acceptance");folder.mkdirs();report.put("runId",runId).put("fontScale",context().getResources().getConfiguration().fontScale).put("scope","Emulator pixel/UI and bound AppWidgetHost only; no real phone or lamps");context().getSharedPreferences(WidgetAppearance.PREFS,0).edit().clear().commit();context().getSharedPreferences("appearance-v1",0).edit().putString("theme","light").commit();SceneStore.ensure(context());String lights=LinkStore.status(context()).toString(),timers=LinkStore.plan(context()).toString(),focus=new JSONObject(context().getSharedPreferences("focus-settings-v1",0).getAll()).toString(),scenes=new JSONObject(context().getSharedPreferences("scene-presets-v1",0).getAll()).toString();check(WidgetAppearance.transparency(context())==0,"upgrade default keeps opaque background");bindHost();
        SettingsActivity menu=(SettingsActivity)open(SettingsActivity.class);check(text(menu,"小组件背景透明度"),"setting discoverable under appearance");ActivityMonitor monitor=addMonitor(WidgetSettingsActivity.class.getName(),null,false);main(()->{menu.widgetAppearanceEntry.performClick();return true;});WidgetSettingsActivity editor=(WidgetSettingsActivity)waitForMonitorWithTimeout(monitor,3000);removeMonitor(monitor);check(editor!=null,"appearance entry opens transparency page");active=editor;main(()->{menu.finish();return true;});check(main(()->editor.slider.getProgress()==0&&editor.value.getText().toString().equals("0%")),"default value shown");for(int id:new int[]{R.id.widget_work,R.id.widget_off,R.id.widget_focus_action})check(main(()->!editor.findViewById(id).hasOnClickListeners()),"appearance preview cannot submit lamp actions");
        drag(editor.slider,37);check(WidgetAppearance.transparency(context())==37,"releasing slider saves actual touch value");waitHost(WidgetAppearance.alpha(37));check(main(()->editor.plate.getImageAlpha()==WidgetAppearance.alpha(37)),"local preview follows drag");screenshot("opacity-settings-light-37");finishActive();WidgetSettingsActivity reopened=(WidgetSettingsActivity)open(WidgetSettingsActivity.class);check(main(()->reopened.slider.getProgress()==37),"saved value survives page recreation");
        for(int n:new int[]{0,50,100}){main(()->{button(reopened,n+"%").performClick();return true;});check(WidgetAppearance.transparency(context())==n,"preset saved "+n);waitHost(WidgetAppearance.alpha(n));screenshot("opacity-settings-light-"+n);}finishActive();
        for(String theme:new String[]{"light","dark"})for(int n:new int[]{0,37,50,100})for(boolean wide:new boolean[]{true,false})main(()->{pixels(theme,n,wide);return true;});context().getSharedPreferences("appearance-v1",0).edit().putString("theme","dark").commit();WidgetAppearance.save(context(),50);waitHost(128);open(WidgetSettingsActivity.class);screenshot("opacity-settings-dark-50");finishActive();
        check(lights.equals(LinkStore.status(context()).toString())&&timers.equals(LinkStore.plan(context()).toString()),"opacity edits never submit light or timer actions");check(focus.equals(new JSONObject(context().getSharedPreferences("focus-settings-v1",0).getAll()).toString())&&scenes.equals(new JSONObject(context().getSharedPreferences("scene-presets-v1",0).getAll()).toString()),"existing focus and scenes unchanged");WidgetAppearance.save(context(),0);context().getSharedPreferences("appearance-v1",0).edit().putString("theme","light").commit();report.put("status","passed").put("checkCount",count).put("checks",checks).put("physicalDeviceTested",false);
    }catch(Exception e){code=1;try{report.put("status","failed").put("error",e.toString()).put("checkCount",count).put("checks",checks);}catch(Exception ignored){}}finally{try{main(()->{if(host!=null){host.stopListening();if(widgetId!=0)host.deleteAppWidgetId(widgetId);}return true;});}catch(Exception ignored){}}
        try{ScreenbarClient.atomic(new File(context().getFilesDir(),"opacity-report.json"),report.toString(2).getBytes("UTF-8"));}catch(Exception e){code=1;}Bundle result=new Bundle();result.putString("result",report.toString());finish(code,result);
    }
}
